import { describe, expect, it } from "vitest"
import type { UnitId } from "@workspace/game-domain"

import summonerList from "../../../../../public/locales/en/npcAbilitySummoners.json"
import { enNpcAbilityText } from "@/test/rules-text"
import { abilitySummons, buildSummonerIds } from "./summoners"

const descriptionOf = (id: string) => enNpcAbilityText[id]?.description
const listed = new Set<string>(summonerList)

describe("summoners", () => {
  it("lists exactly the abilities whose committed English text summons", () => {
    // npcAbilitySummoners.json is generated by scripts/generate-ability-text-i18n.mjs with a copy of
    // the summon patterns; it must match them over the committed descriptions.
    const expected = Object.keys(enNpcAbilityText)
      .filter((id) => abilitySummons(descriptionOf(id) ?? ""))
      .sort()
    const unlisted = expected.filter((id) => !listed.has(id))
    const extra = summonerList.filter((id) => !expected.includes(id))
    expect({ unlisted, extra }).toEqual({ unlisted: [], extra: [] })
    expect(summonerList).toEqual([...summonerList].sort())
  })

  it("finds the abilities that bring a unit onto the battlefield", () => {
    for (const id of [
      "AberrantHypermorph",
      "GrotTank",
      "SupremeCommander",
      "SwornProtector",
      "Poxwalkers",
    ]) {
      expect(abilitySummons(descriptionOf(id) ?? ""), id).toBe(true)
      expect(listed.has(id), id).toBe(true)
    }
  })

  it("skips abilities that only buff or target existing summons", () => {
    for (const id of [
      "AmuletOfTheVoidwyrm",
      "MawClawsOfThyrax",
      "ShockAssault",
    ]) {
      expect(abilitySummons(descriptionOf(id) ?? ""), id).toBe(false)
      expect(listed.has(id), id).toBe(false)
    }
  })

  it("puts Hollan in the set and leaves a non-summoner out", () => {
    const summoners = buildSummonerIds(
      [
        {
          id: "genesBiophagus" as UnitId,
          activeAbilityNames: ["AberrantHypermorph"],
          passiveAbilityNames: [],
        },
        {
          id: "ultraInceptorSgt" as UnitId,
          activeAbilityNames: ["DeathFromAbove"],
          passiveAbilityNames: ["ShockAssault"],
        },
        {
          id: "someone" as UnitId,
          activeAbilityNames: ["NoSuchAbility"],
          passiveAbilityNames: ["ShockAssault"],
        },
      ],
      (id) => listed.has(id)
    )
    expect([...summoners].sort()).toEqual([
      "genesBiophagus",
      "ultraInceptorSgt",
    ])
  })
})
